// Hot reload, after upstream HTNHotReloadDemo: the Wanderer walks with the validation domain revision A; a reload
// swaps in revision B (or a source that fails to compile) on the SAME world and host. The running step is dropped,
// the planner plans again, and the new plan says which revision made it. Revisions come from the self-test template
// (HTNHotReloadDemo/Validation/Wanderer.domain, @REVISION@ replaced), generated by scripts/htn-lab.ts.
import { formatAtom, int, list, sym } from '../../htn-planner'
import type { WorldState } from '../../htn-planner'
import { BROKEN_DIAGNOSTICS, BROKEN_SOURCE } from './generated/hot-reload/broken'
import { wandererRevADomain } from './generated/hot-reload/WandererRevA.htn'
import { wandererRevBDomain } from './generated/hot-reload/WandererRevB.htn'
import { WandererWorld } from './gallery/wanderer'
import type { GalleryReload, GalleryStation } from './stations'

export const marker = (rev: string) => `!say "reload-validation-${rev}"`

export const HOT_RELOADS: GalleryReload[] = [
  { name: 'B', domain: wandererRevBDomain, marker: marker('B') },
  { name: 'broken source', error: `${BROKEN_SOURCE}  ->  ${BROKEN_DIAGNOSTICS.join('; ')}` },
  { name: 'A', domain: wandererRevADomain, marker: marker('A') }
]

/** What the reload must keep: the wanderer's place. */
export function wandererLocation(world: WorldState): string {
  const at = world.rows('wanderer_location', 1)[0]?.[0]
  return at ? formatAtom(at) : '-'
}

const walking = (w: WorldState) => {
  w.add('wanderer_state', sym('walking'))
  w.add('wanderer_location', list(int(0), int(0)))
  w.add('wanderer_destination', list(int(15), int(0)))
}

export const HOT_RELOAD_STATION: GalleryStation = {
  id: 'hot-reload',
  title: 'Hot reload',
  blurb: 'swap the domain while it walks: same world, new plan',
  domain: wandererRevADomain,
  host: world => new WandererWorld(world),
  reloads: HOT_RELOADS,
  keeps: wandererLocation,
  scenarios: [
    {
      name: 'rev A walking (path query pending)',
      method: 'run',
      setup: walking,
      expect: [marker('A'), '&talk_about_destination', '!after_destination_comment']
    }
  ]
}
